/**
 * The canonical grid, from canon.json (generated by `cargo xtask schema`): checks that a verse id
 * names a real verse. Pure: no `ctx`.
 */
import { Effect } from "effect"
import { InvalidRequest } from "../../shared/Errors.js"
import canon from "./canon.json" with { type: "json" }

export interface VerseParts {
  readonly book: number
  readonly chapter: number
  readonly verse: number
}

/** The parts of a verse id, if it is on the grid. */
export const verseParts = (id: number): VerseParts | null => {
  if (!Number.isInteger(id) || id < 0) return null
  const book = Math.floor(id / 1_000_000)
  const chapter = Math.floor(id / 1_000) % 1_000
  const verse = id % 1_000
  const verses = canon.books[book]?.verses[chapter - 1]
  if (chapter < 1 || verses === undefined) return null
  return verse >= 1 && verse <= verses ? { book, chapter, verse } : null
}

/** "John 3:16" for a verse id on the grid. */
export const describeVerse = (id: number): string => {
  const parts = verseParts(id)
  return parts ? `${canon.books[parts.book]!.name} ${parts.chapter}:${parts.verse}` : `#${id}`
}

/** The id itself when it is a verse on the grid; otherwise an `invalid_request`. */
export const checkVerse = (id: number): Effect.Effect<number, InvalidRequest> =>
  verseParts(id) === null
    ? Effect.fail(new InvalidRequest({ message: `${id} isn't a verse on the canonical grid.` }))
    : Effect.succeed(id)
